import{_ as i,a0 as d,w as s,s as r,I as t,x as l,a1 as o,A as p,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const O=JSON.parse('{"title":"OpenBSD 7.3 发布，包含新功能和更新 | LCTT x X-CMD","titleTemplate":false,"description":"OpenBSD 7.3 发布，包含新功能和更新 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OpenBSD 7.3 发布，包含新功能和更新 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OpenBSD 7.3 发布，包含新功能和更新 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230412.1 ⭐️⭐️ OpenBSD 7.3 Released with New Features and Updates","title":"OpenBSD 7.3 发布，包含新功能和更新","tag":"202304","desc":""},"relativePath":"202304/20230412.1 ⭐️⭐️ OpenBSD 7.3 Released with New Features and Updates.md","filePath":"[post].md"}'),u={name:"202304/20230412.1 ⭐️⭐️ OpenBSD 7.3 Released with New Features and Updates.md"};function m(D,e,f,g,S,w){const n=d("Link");return s(),r("div",null,[e[20]||(e[20]=t("h1",{id:"openbsd-7-3-发布-包含新功能和更新",tabindex:"-1"},[l("OpenBSD 7.3 发布，包含新功能和更新 "),t("a",{class:"header-anchor",href:"#openbsd-7-3-发布-包含新功能和更新","aria-label":"Permalink to “OpenBSD 7.3 发布，包含新功能和更新”"},"​")],-1)),e[21]||(e[21]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/16/150654wtvhflqgvmfdg6hv.jpg",alt:""})],-1)),e[22]||(e[22]=t("blockquote",null,[t("p",null,"OpenBSD 7.3 正式发布，有大量的软件包更新和改进。")],-1)),e[23]||(e[23]=t("p",null,[t("img",{src:"https://debugpointnews.com/wp-content/uploads/2023/04/OpenBSD-desktop-7-fvwm.jpg",alt:"OpenBSD desktop (7+) fvwm"})],-1)),t("p",null,[e[1]||(e[1]=l("OpenBSD 7.3 已经正式 ",-1)),o(n,{href:"https://www.openbsd.org/73.html"},{default:p(()=>[...e[0]||(e[0]=[l("发布",-1)])]),_:1}),e[2]||(e[2]=l("，这是该系统的第 54 个版本。这个最新的版本建立在 OpenBSD 令人印象深刻的傲人记录之上 —— 它是一个安全可靠的操作系统，在二十多年的使用过程中，在默认安装中只发现了两个远程漏洞。",-1))]),e[24]||(e[24]=a('<p>与以前的版本一样，OpenBSD 7.3 在广泛的系统领域提供了显著的改进。其中包括内核的改进，如增加了 <code>waitid(2)</code>、<code>pinsyscall(2)</code>、 <code>getthrname(2)</code> 和 <code>setthrname(2)</code> 函数，以及 <code>waitid(2)</code> 的 <code>WTRAPPED</code> 选项，等等。此外，新的内核 <code>autoconf_serial sysctl(8)</code> 允许用户区监控内核设备树状态的变化。</p><p>直接渲染管理器和图形驱动已经更新，引入了对 Ryzen 7000 “Raphael” 和 Ryzen 7020 和 7045 系列处理器以及 Radeon RX 7900 XT/XTX “Navi 31” 的支持，并改进了苹果芯片笔记本电脑和联想 x13s 的问题的解决方案。</p><p>此外，还改进了对网络硬件的支持，例如启用了 <code>em(4)</code> IPv4、 TCP 和 UDP 校验卸载，以及 82575、 82576、 i350 和 i210 芯片组设备上的硬件 VLAN 标记， 以及改进了 <code>mcx(4)</code> 性能。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/04/OpenBSD-7.3-installation.jpg" alt="OpenBSD 7.3 安装"></p><p>除了上述的改进，OpenBSD 7.3 还包括一系列新的或改进的硬件和软件对 <ruby>端口源码包<rt>Port</rt></ruby> 和 <ruby>二进制软件包<rt>Package</rt></ruby> 的支持。一些来自外部供应商的主要组件包括 Xenocara、LLVM/Clang、GCC、Perl、NSD、Unbound、Ncurses、Binutils、Gdb、Awk 和 Expat。</p><p>OpenBSD 以最安全、最可靠的操作系统之一而闻名。在过去的二十年里，它的默认安装中只有两个远程漏洞，这一记录令人印象深刻。随着 OpenBSD 7.3 的发布，用户可以期待在几乎所有的系统领域都有显著的改进。</p><p>这个版本的内核改进，如增加了 <code>waitid(2)</code>、<code>pinsyscall(2)</code>、<code>getthrname(2)</code>、<code>setthrname(2)</code> 和 <code>clockintr(9)</code>，将为用户提供更简化的体验。Direct Rendering Manager 和图形驱动也得到了更新，包括对 Ryzen 7000 “Raphael”、Radeon RX 7900 XT/XTX “Navi 31” 和 Radeon RX 7600M（XT）等新设备的支持。</p><p>OpenBSD 7.3 还包括改进的网络硬件支持，在 82575、82576、i350 和 i210 芯片组的设备上启用 <code>em(4)</code> IPv4、TCP 和 UDP 校验和卸载以及硬件 VLAN 标记。此外，通过使用基于中断的命令完成，<code>mcx(4)</code> 的性能得到了提高。</p><p>至于端口源码包和二进制软件包，OpenBSD 7.3 包括了最新版本的应用程序、桌面和关键软件包。下面是关键端口源码包和二进制软件包的新项目列表：</p><p><strong>桌面和应用</strong></p><ul><li>Chromium 111.0.5563.110</li><li>GNOME 43.3</li><li>KDE 应用 22.12.3</li><li>KDE 框架 5.103.0</li><li>Xfce 4.18</li><li>Krita 5.1.5</li><li>LibreOffice 7.5.1.2</li><li>Mozilla Firefox 111.0 和 ESR 102.9.0</li><li>Mozilla Thunderbird 102.9.0</li></ul><p><strong>核心开发软件包</strong></p><ul><li>Mutt 2.2.9 和 NeoMutt 20220429</li><li>Node.js 18.15.0</li><li>OCaml 4.12.1</li><li>OpenLDAP 2.6.4</li><li>PHP 7.4.33, 8.0.28, 8.1.16 和 8.2.3</li><li>Postfix 3.5.17 和 3.7.3</li><li>PostgreSQL 15.2</li><li>Python 2.7.18, 3.9.16, 3.10.10 和 3.11.2</li><li>Qt 5.15.8 和 6.4.2</li><li>R 4.2.1</li><li>Ruby 3.0.5, 3.1.3 和 3.2.1</li><li>Rust 1.68.0</li><li>Sudo 1.9.13.3</li><li>MariaDB 10.9.4</li><li>Mono 6.12.0.182</li></ul><p>总的来说，最新发布的 OpenBSD 继续为用户提供安全可靠的操作系统，同时也在系统的各个领域进行了重大改进。我们鼓励用户升级到 OpenBSD 7.3，以利用这些新功能和改进。</p><p>OpenBSD 7.3 可以从官方网站下载，并有全面的发布说明，详细介绍了所有的新功能和改进。</p>',15)),t("blockquote",null,[t("p",null,[t("strong",null,[o(n,{href:"https://cdn.openbsd.org/pub/OpenBSD/7.3/"},{default:p(()=>[...e[3]||(e[3]=[l("下载 OpenBSD 7.3（所有架构）",-1)])]),_:1})])])]),t("blockquote",null,[t("p",null,[t("strong",null,[o(n,{href:"https://www.openbsd.org/plus73.html"},{default:p(()=>[...e[4]||(e[4]=[l("详细的更新日志",-1)])]),_:1})])])]),e[25]||(e[25]=t("p",null,[t("em",null,"（题图： MJ:Future computer with transparent screen, metal box, hd, ultra detailed, sci-fi）")],-1)),e[26]||(e[26]=t("hr",null,null,-1)),t("p",null,[e[6]||(e[6]=l("via: ",-1)),o(n,{href:"https://debugpointnews.com/openbsd-7-3/"},{default:p(()=>[...e[5]||(e[5]=[l("https://debugpointnews.com/openbsd-7-3/",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=l("作者：",-1)),o(n,{href:"https://debugpointnews.com/author/dpicubegmail-com/"},{default:p(()=>[...e[7]||(e[7]=[l("arindam",-1)])]),_:1}),e[12]||(e[12]=l(" 选题：",-1)),o(n,{href:"https://github.com/lkxed/"},{default:p(()=>[...e[8]||(e[8]=[l("lkxed",-1)])]),_:1}),e[13]||(e[13]=l(" 译者：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[9]||(e[9]=[l("wxy",-1)])]),_:1}),e[14]||(e[14]=l(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[10]||(e[10]=[l("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=l("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[15]||(e[15]=[l("LCTT",-1)])]),_:1}),e[18]||(e[18]=l(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:p(()=>[...e[16]||(e[16]=[l("Linux中国",-1)])]),_:1}),e[19]||(e[19]=l(" 荣誉推出",-1))])])}const T=i(u,[["render",m]]);export{O as __pageData,T as default};
